CREATE PROCEDURE [dbo].[PriceSegmentsList] @BusinessId UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON;
 SELECT l.PriceListId,N'PriceList',l.Code,l.Name,l.IsActive,l.CreatedAt,(SELECT COUNT(DISTINCT i.ProductId) FROM dbo.PriceListItems i WHERE i.PriceListId=l.PriceListId AND i.IsActive=1),(SELECT COUNT(*) FROM dbo.CustomerPricingSettings s JOIN dbo.Customers c ON c.CustomerId=s.CustomerId WHERE c.BusinessId=l.BusinessId AND s.PriceListId=l.PriceListId),CAST(NULL AS decimal(9,6)) FROM dbo.PriceLists l WHERE l.BusinessId=@BusinessId
 UNION ALL
 SELECT c.PriceChannelId,N'PriceChannel',c.Code,c.Name,c.IsActive,c.CreatedAt,0,(SELECT COUNT(*) FROM dbo.CustomerPricingSettings s JOIN dbo.Customers customer ON customer.CustomerId=s.CustomerId WHERE customer.BusinessId=c.BusinessId AND s.PriceChannelId=c.PriceChannelId),COALESCE((SELECT TOP(1) r.NumericValue FROM dbo.PriceChannelRules r WHERE r.PriceChannelId=c.PriceChannelId AND r.RuleKind=N'PercentageVariation' AND r.AppliesTo=N'AllProducts' AND r.IsActive=1 AND r.ValidFrom<=SYSDATETIMEOFFSET() AND(r.ValidUntil IS NULL OR r.ValidUntil>SYSDATETIMEOFFSET()) ORDER BY r.ValidFrom DESC),0) FROM dbo.PriceChannels c WHERE c.BusinessId=@BusinessId ORDER BY 2,4;
END
